using System.Windows;using System.Windows.Controls;using System.Windows.Media;
namespace Pharmacie.Wpf;
public class MainWindow:Window{readonly PharmacyData data;readonly StackPanel content=new();readonly TextBlock title=new();readonly Brush teal=new SolidColorBrush(Color.FromRgb(32,162,138));readonly Brush navy=new SolidColorBrush(Color.FromRgb(13,45,57));readonly List<Product> cart=[];
public MainWindow(){data=DataStore.Load();Title="PharmaFlow - Gestion de pharmacie";Width=1200;Height=760;WindowStartupLocation=WindowStartupLocation.CenterScreen;BuildShell();ShowHome();}
void BuildShell(){var root=new Grid();root.RowDefinitions.Add(new RowDefinition{Height=new GridLength(82)});root.RowDefinitions.Add(new RowDefinition());var header=new DockPanel{Margin=new Thickness(28,0,28,0)};var brand=new TextBlock{Text="✚ PharmaFlow",Foreground=navy,FontSize=21,FontWeight=FontWeights.Bold,VerticalAlignment=VerticalAlignment.Center};header.Children.Add(brand);var nav=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Right};AddMenu(nav,"Accueil",ShowHome);AddMenu(nav,"Produits",ShowProducts);AddMenu(nav,"Vente",ShowSale);AddMenu(nav,"Stocks",ShowStock);AddMenu(nav,"Rapports",ShowReports);AddMenu(nav,"Paramètres",ShowSettings);header.Children.Add(nav);root.Children.Add(new Border{Background=Brushes.White,BorderBrush=new SolidColorBrush(Color.FromRgb(226,234,236)),BorderThickness=new Thickness(0,0,0,1),Child=header});var scroll=new ScrollViewer{Content=content,Margin=new Thickness(42,32,42,32)};Grid.SetRow(scroll,1);root.Children.Add(scroll);Content=root;}void AddMenu(Panel p,string text,Action action){var b=new Button{Content=text,Padding=new Thickness(13),Margin=new Thickness(0,4,0,4),HorizontalContentAlignment=HorizontalAlignment.Center,Foreground=navy,Background=Brushes.Transparent,BorderBrush=Brushes.Transparent,FontSize=13};b.MouseEnter+=(s,e)=>b.Background=new SolidColorBrush(Color.FromArgb(45,255,255,255));b.MouseLeave+=(s,e)=>b.Background=Brushes.Transparent;b.Click+=(s,e)=>action();p.Children.Add(b);}
TextBlock T(string s,int n=16)=>new(){Text=s,FontSize=n,Margin=new Thickness(0,6,0,6)};void Clear(string t){title.Text=t;content.Children.Clear();}
Border Card(string l,string v){var st=new StackPanel();st.Children.Add(T(l,13));st.Children.Add(new TextBlock{Text=v,FontSize=24,FontWeight=FontWeights.Bold,Foreground=teal,Margin=new Thickness(0,8,0,0)});return new Border{Child=st,Background=Brushes.White,BorderBrush=new SolidColorBrush(Color.FromRgb(226,234,236)),BorderThickness=new Thickness(1),CornerRadius=new CornerRadius(10),Padding=new Thickness(18),Margin=new Thickness(0,0,14,14),Width=210};}
Button Action(string text,RoutedEventHandler click,bool primary=true){var b=new Button{Content=text,Padding=new Thickness(13,9,13,9),Margin=new Thickness(0,5,8,5),Background=primary?teal:Brushes.White,Foreground=primary?Brushes.White:navy,BorderBrush=primary?teal:new SolidColorBrush(Color.FromRgb(210,220,223)),BorderThickness=new Thickness(1),FontWeight=FontWeights.Bold};b.Click+=click;b.MouseEnter+=(s,e)=>b.Opacity=.8;b.MouseLeave+=(s,e)=>b.Opacity=1;return b;}
void ShowHome(){Clear("Accueil");var hero=new Border{Background=navy,CornerRadius=new CornerRadius(18),Padding=new Thickness(38),Margin=new Thickness(0,0,0,22)};var hs=new StackPanel();hs.Children.Add(new TextBlock{Text="PHARMAFLOW",Foreground=new SolidColorBrush(Color.FromRgb(125,225,199)),FontSize=14,FontWeight=FontWeights.Bold});hs.Children.Add(new TextBlock{Text="La gestion de votre pharmacie,\nsimplement et efficacement.",Foreground=Brushes.White,FontSize=32,FontWeight=FontWeights.Bold,Margin=new Thickness(0,10,0,8)});hs.Children.Add(new TextBlock{Text="Pilotez vos produits, votre stock et vos ventes depuis un espace unique.",Foreground=new SolidColorBrush(Color.FromRgb(220,235,238)),FontSize=16});hs.Children.Add(Action("Commencer maintenant",(s,e)=>ShowDashboard()));hero.Child=hs;content.Children.Add(hero);content.Children.Add(T("Tout ce dont votre pharmacie a besoin",23));var features=new WrapPanel();features.Children.Add(Card("Gestion des produits",$"{data.Products.Count} produits"));features.Children.Add(Card("Stock maîtrisé",$"{data.Products.Count(p=>p.Stock<=p.Minimum)} alertes"));features.Children.Add(Card("Ventes rapides",$"{data.Sales.Count} ventes"));content.Children.Add(features);content.Children.Add(T("Accès rapide",22));var quick=new WrapPanel();quick.Children.Add(Action("Gérer les produits",(s,e)=>ShowProducts(),false));quick.Children.Add(Action("Nouvelle vente",(s,e)=>ShowSale(),false));quick.Children.Add(Action("Consulter les stocks",(s,e)=>ShowStock(),false));content.Children.Add(quick);}
void ShowDashboard(){Clear("Tableau de bord");content.Children.Add(T("Bonjour Alain,",29));content.Children.Add(T("Vue d’ensemble de votre pharmacie",15));var row=new WrapPanel{Margin=new Thickness(0,20,0,15)};row.Children.Add(Card("Produits actifs",data.Products.Count.ToString()));row.Children.Add(Card("Ruptures",data.Products.Count(p=>p.Stock==0).ToString()));row.Children.Add(Card("Ventes enregistrées",data.Sales.Count.ToString()));row.Children.Add(Card("Chiffre d’affaires",$"{data.Sales.Sum(s=>s.Total):N0} FCFA"));content.Children.Add(row);content.Children.Add(T("Alertes",20));foreach(var p in data.Products.Where(p=>p.Stock<=p.Minimum))content.Children.Add(T($"⚠ {p.Name} : {p.Status} ({p.Stock} unité(s))",15));}
void ShowProducts(){Clear("Produits");content.Children.Add(T("Catalogue des produits",27));var bar=new StackPanel{Orientation=Orientation.Horizontal};var search=new TextBox{Width=330,Padding=new Thickness(10)};bar.Children.Add(search);bar.Children.Add(Action("＋ Ajouter un produit",(s,e)=>AddProductForm()));content.Children.Add(bar);var grid=new DataGrid{ItemsSource=data.Products,AutoGenerateColumns=true,IsReadOnly=true,Height=330,Margin=new Thickness(0,15,0,0)};search.TextChanged+=(s,e)=>grid.ItemsSource=data.Products.Where(p=>p.Name.Contains(search.Text,StringComparison.OrdinalIgnoreCase)||p.Reference.Contains(search.Text,StringComparison.OrdinalIgnoreCase));content.Children.Add(grid);}
void AddProductForm(){Clear("Ajouter un produit");content.Children.Add(T("Nouveau produit",25));var name=new TextBox{Padding=new Thickness(10)};var reference=new TextBox{Padding=new Thickness(10)};var price=new TextBox{Padding=new Thickness(10)};var stock=new TextBox{Padding=new Thickness(10)};content.Children.Add(T("Désignation"));content.Children.Add(name);content.Children.Add(T("Référence"));content.Children.Add(reference);content.Children.Add(T("Prix de vente"));content.Children.Add(price);content.Children.Add(T("Stock initial"));content.Children.Add(stock);content.Children.Add(Action("Enregistrer le produit",(s,e)=>{if(string.IsNullOrWhiteSpace(name.Text)||!decimal.TryParse(price.Text,out var pr)||!int.TryParse(stock.Text,out var st)){MessageBox.Show("Veuillez remplir correctement les champs.");return;}data.Products.Add(new Product{Reference=reference.Text,Name=name.Text,Price=pr,Stock=st,Minimum=5,Lot="LOT-INITIAL",Expiry=DateTime.Today.AddYears(1)});DataStore.Save(data);MessageBox.Show("Produit ajouté.");ShowProducts();}));}
void ShowSale(){Clear("Vente & caisse");content.Children.Add(T("Produits disponibles",25));foreach(var p in data.Products.Where(p=>p.Stock>0))content.Children.Add(Action($"{p.Name} - {p.Price:N0} FCFA | stock {p.Stock}",(s,e)=>{p.Stock--;data.Sales.Add(new Sale{Number="V-"+(data.Sales.Count+1001),Date=DateTime.Now,Total=p.Price,Payment="Espèces"});DataStore.Save(data);MessageBox.Show("Vente validée et stock mis à jour.");ShowSale();},false));}
void ShowStock(){Clear("Stocks & approvisionnement");content.Children.Add(T("Réceptions, inventaires et mouvements",26));content.Children.Add(Action("＋ Réceptionner 10 unités",(s,e)=>{if(data.Products.Count>0)data.Products[0].Stock+=10;DataStore.Save(data);ShowStock();}));content.Children.Add(Action("Valider l’inventaire",(s,e)=>{DataStore.Save(data);MessageBox.Show("Inventaire sauvegardé.");},false));content.Children.Add(new DataGrid{ItemsSource=data.Products,AutoGenerateColumns=true,IsReadOnly=true,Height=300,Margin=new Thickness(0,12,0,0)});}
void ShowReports(){Clear("Rapports");content.Children.Add(T("Rapport des ventes",26));content.Children.Add(T($"Chiffre d’affaires : {data.Sales.Sum(s=>s.Total):N0} FCFA",20));content.Children.Add(new DataGrid{ItemsSource=data.Sales,AutoGenerateColumns=true,IsReadOnly=true,Height=300});}
void ShowSettings(){Clear("Paramètres");content.Children.Add(T("Paramètres de la pharmacie",27));var name=new TextBox{Text="Pharmacie La Santé",Padding=new Thickness(10),Margin=new Thickness(0,5,0,10)};var phone=new TextBox{Text="+242 06 123 45 67",Padding=new Thickness(10),Margin=new Thickness(0,5,0,10)};var currency=new ComboBox{Padding=new Thickness(8),Margin=new Thickness(0,5,0,15)};currency.Items.Add("FCFA");currency.Items.Add("EUR");currency.SelectedIndex=0;content.Children.Add(T("Nom de la pharmacie"));content.Children.Add(name);content.Children.Add(T("Téléphone"));content.Children.Add(phone);content.Children.Add(T("Devise"));content.Children.Add(currency);content.Children.Add(Action("Enregistrer les paramètres",(s,e)=>MessageBox.Show("Paramètres enregistrés avec succès.")));content.Children.Add(T("Sécurité et sauvegarde",22));content.Children.Add(T("Les données sont sauvegardées localement sur cet ordinateur.",15));}}


